function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const SIX = ['nexcore', 'recex', 'washtro', 'formverse', 'pixelence', 'doffair'];

const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const stRaw = $('Read STARTUPS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
if (trk.length < 200) { throw new Error('ABORT: tracker only ' + trk.length + ' rows - truncated'); }

const TAGS = [
  ['health', /health|medtech|bio|clinic|pharma|life science|wellness|fitness|diagnost/],
  ['fintech', /fintech|lending|insur|payment|banking|wealth|credit|financial/],
  ['saas', /saas|b2b|enterprise|software|platform|api|devtool|cloud/],
  ['consumer', /consumer|d2c|b2c|retail|fmcg|food|beverage|fashion|beauty|apparel|coffee|restaurant|cafe|grocer/],
  ['deeptech', /deeptech|deep tech|\bai\b|artificial intelligence|\bml\b|robot|iot|semiconductor|space|drone|quantum|computer vision/],
  ['climate', /climate|clean|energy|solar|ev\b|electric vehicle|sustain|green|water|waste|carbon/],
  ['edtech', /edtech|education|learning|skill|training|exam/],
  ['logistics', /logistic|supply chain|mobility|delivery|freight|shipping|transport/],
  ['agritech', /agri|farm|agtech/],
  ['hrtech', /hrtech|\bhr\b|recruit|talent|hiring|staffing/],
  ['proptech', /proptech|real estate|construction|coworking|interior|windoor/],
  ['media', /media|gaming|content|entertainment|creator|social|dating|travel/]
];
function tagsOf(txt) {
  const t = s(txt).toLowerCase();
  const out = {};
  for (const p of TAGS) { if (p[1].test(t)) { out[p[0]] = 1; } }
  return Object.keys(out);
}
function startupStage(txt) {
  const t = s(txt).toLowerCase();
  if (/series b|growth|series c/.test(t)) { return 4; }
  if (/series a/.test(t)) { return 3; }
  if (/pilot|traction|early revenue|revenue|mvp|launched/.test(t)) { return 2; }
  if (/\bseed\b/.test(t) && !/pre-?seed/.test(t)) { return 1; }
  if (/pre-?seed|ideation|concept|idea|prototype/.test(t)) { return 0; }
  return 1;
}
function investorBand(txt) {
  const t = s(txt).toLowerCase();
  const h = [];
  if (/pre-?seed|preseed/.test(t)) { h.push(0); }
  if (/\bseed\b/.test(t)) { h.push(1); }
  if (/pilot|traction|early|pre-?series a|pre series a/.test(t)) { h.push(2); }
  if (/series a/.test(t)) { h.push(3); }
  if (/series b|series c|growth|late|pre-?ipo/.test(t)) { h.push(4); }
  if (!h.length) { return [0, 4]; }
  return [Math.min.apply(null, h), Math.max.apply(null, h)];
}
// USD at 85: $1M = 8.5 Cr, $1K = 0.0085 Cr
function toCr(txt) {
  const t = s(txt).replace(/,/g, '');
  if (!t) { return null; }
  let m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*M/i);
  if (m) { return parseFloat(m[1]) * 8.5; }
  m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*K/i);
  if (m) { return parseFloat(m[1]) * 0.0085; }
  m = t.match(/([\d.]+)\s*(?:-|to|–)\s*[\d.]+\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Lakh/i);
  if (m) { return parseFloat(m[1]) / 100; }
  return null;
}
// these three cells put the true minimum after a larger figure - read the real floor
const FLOOR_FIX = { a2dventures: 0.85, mintvc: 0.5, pipersireca: 1.0 };

const book = [];
const seen = {};
for (const r of invRaw) {
  const n = s(r.investor);
  if (!n) { continue; }
  if (s(r.do_not_contact).toLowerCase() === 'yes') { continue; }
  const k = nz(n);
  if (seen[k]) { continue; }
  seen[k] = 1;
  const sec = s(r.sector);
  let floor = toCr(r.cheque_inr_cr);
  if (FLOOR_FIX[k] !== undefined) { floor = FLOOR_FIX[k]; }
  book.push({ key: k, name: n, email: s(r.email), agnostic: /agnostic/i.test(sec),
    tags: tagsOf(sec), band: investorBand(r.stage), floor: floor });
}

const cols = Object.keys(trk[0] || {});
let cInv = null; const cDeals = [];
for (const c of cols) {
  const l = c.toLowerCase();
  if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; }
  if (l.indexOf('deals shared') >= 0 || l.indexOf('latest deal') >= 0 || l.indexOf('picked') >= 0) { cDeals.push(c); }
}
const trkText = [];
for (const r of trk) {
  const iv = nz(r[cInv]);
  if (!iv) { continue; }
  let blob = '';
  for (const c of cDeals) { blob += ' ' + s(r[c]); }
  trkText.push({ inv: iv, blob: nz(blob) });
}

const pairedBy = {};
for (const p of pipe) {
  const k = nz(p.startup);
  if (!k) { continue; }
  if (!pairedBy[k]) { pairedBy[k] = {}; }
  pairedBy[k][nz(p.investor)] = 1;
}
let maxN = 0;
for (const p of pipe) {
  const id = s(p.deal_id);
  if (id.charAt(0) === 'D') { const v = parseInt(id.slice(1), 10); if (!isNaN(v) && v > maxN) { maxN = v; } }
}
function weekdays(n, y, m, d) {
  const a = []; const dt = new Date(Date.UTC(y, m - 1, d));
  while (a.length < n) { const w = dt.getUTCDay(); if (w !== 0 && w !== 6) { a.push(dt.toISOString().slice(0, 10)); } dt.setUTCDate(dt.getUTCDate() + 1); }
  return a;
}

const rows = [];
const summary = [];
let n = maxN;
for (const r of stRaw) {
  const name = s(r.startup);
  if (SIX.indexOf(nz(name)) < 0) { continue; }
  if (s(r.active).toLowerCase() !== 'yes') { continue; }
  const k = nz(name);
  const paired = Object.assign({}, pairedBy[k] || {});
  let trkExcluded = 0;
  for (const t of trkText) {
    if (k.length > 3 && t.blob.indexOf(k) >= 0 && !paired[t.inv]) { paired[t.inv] = 1; trkExcluded++; }
  }
  const sTags = tagsOf(s(r.sector));
  const si = startupStage(r.stage);
  const raise = toCr(r.raise_inr_cr);
  if (raise === null) { throw new Error('ABORT: cannot read raise for ' + name); }

  const hits = [];
  for (const b of book) {
    if (paired[b.key]) { continue; }
    let overlap = false;
    for (const t of b.tags) { if (sTags.indexOf(t) >= 0) { overlap = true; break; } }
    const sec = b.agnostic ? (overlap ? 28 : 20) : (overlap ? 40 : 0);
    const lo = b.band[0], hi = b.band[1];
    const stg = (si >= lo && si <= hi) ? 30 : ((si >= lo - 1 && si <= hi + 1) ? 15 : 0);
    let chq;
    if (b.floor === null) { chq = 18; }
    else if (raise >= b.floor) { chq = 30; }
    else { chq = 0; }
    if (sec === 0 || stg === 0 || chq === 0) { continue; }
    const total = sec + stg + chq;
    if (total < 70) { continue; }
    hits.push({ name: b.name, email: b.email, score: total });
  }
  hits.sort(function (a, b) { return b.score - a.score || a.name.localeCompare(b.name); });
  const days = weekdays(Math.ceil(hits.length / 2) + 1, 2026, 9, 10);
  for (let i = 0; i < hits.length; i++) {
    n++;
    let pad = String(n);
    while (pad.length < 5) { pad = '0' + pad; }
    const h = hits[i];
    rows.push({ json: { deal_id: 'D' + pad, startup: name, owner: s(r.owner), investor: h.name,
      email: h.email, cc: '', priority: h.score, deal_shared: 'No', next_action: 'Initial',
      next_due: days[Math.floor(i / 2)],
      notes: (h.score >= 85 ? 'Very High' : 'High') + ' match (' + h.score + ') - re-matched at 70+ 2026-09-09' } });
  }
  summary.push({ startup: name, raise_cr: raise, added: hits.length, tracker_excluded: trkExcluded });
}

if (rows.length === 0) { throw new Error('ABORT: no matches produced'); }
if (rows.length > 400) { throw new Error('ABORT: ' + rows.length + ' rows exceeds guard of 400'); }
console.log('adding ' + rows.length, JSON.stringify(summary));
return rows;
